-- 3. 15 Indices FKs y compuestos de alto impacto
CREATE INDEX IF NOT EXISTS idx_obligaciones_pago_concepto_tipo_fk ON public.obligaciones_pago (concepto_id, tipo_concepto);
CREATE INDEX IF NOT EXISTS idx_solicitudes_mat_pub_mat_est_anio_fk ON public.solicitudes_matricula_publica (matricula_id, estudiante_id, anio_lectivo_id);
CREATE INDEX IF NOT EXISTS idx_solicitudes_mat_pub_sec_anio_grado_fk ON public.solicitudes_matricula_publica (seccion_id, anio_lectivo_id, grado_id);
CREATE INDEX IF NOT EXISTS idx_importaciones_biometrico_lote_fk ON public.importaciones_biometrico (lote_id);
CREATE INDEX IF NOT EXISTS idx_solicitudes_cambio_responsable_fk ON public.solicitudes_cambio (responsable_id);
CREATE INDEX IF NOT EXISTS idx_solicitudes_cambio_eventos_actor_fk ON public.solicitudes_cambio_eventos (actor_id);
CREATE INDEX IF NOT EXISTS idx_solicitudes_cambio_notif_sol_evento_fk ON public.solicitudes_cambio_notificaciones (solicitud_id, evento_id);
CREATE INDEX IF NOT EXISTS idx_pagos_transacciones_estado_fecha ON public.pagos_transacciones (estado_pago, fecha_pago DESC);
CREATE INDEX IF NOT EXISTS idx_asistencias_aula_fecha_estado ON public.asistencias_aula (fecha_sesion, estado);
CREATE INDEX IF NOT EXISTS idx_horarios_seccion_anio_sec_activo ON public.horarios_seccion (anio_lectivo_id, seccion_id, dia_semana, bloque_horario_id) WHERE (activo IS TRUE);
CREATE INDEX IF NOT EXISTS idx_horarios_seccion_anio_doc_activo ON public.horarios_seccion (anio_lectivo_id, docente_usuario_id, dia_semana, bloque_horario_id) WHERE (activo IS TRUE);
CREATE INDEX IF NOT EXISTS idx_mallas_grado_anio_grado_activo ON public.mallas_horarias_grado (anio_lectivo_id, grado_id, dia_semana, bloque_horario_id) WHERE (activo IS TRUE);
CREATE INDEX IF NOT EXISTS idx_asignaciones_docentes_anio_sec ON public.asignaciones_docentes (anio_lectivo_id, seccion_id, area_curricular_id);
CREATE INDEX IF NOT EXISTS idx_asignaciones_docentes_docente_anio ON public.asignaciones_docentes (docente_usuario_id, anio_lectivo_id);
CREATE INDEX IF NOT EXISTS idx_usuario_roles_rol_usuario ON public.usuario_roles (rol_id, usuario_id);

-- 4. Vistas administrativas con security_invoker = true
ALTER VIEW IF EXISTS public.v_ranking_merito_cneb SET (security_invoker = true);

CREATE OR REPLACE VIEW public.v_resumen_matriculas_seccion
WITH (security_invoker = true) AS
SELECT al.id AS anio_lectivo_id,
       al.anio,
       n.id AS nivel_id,
       n.codigo_nivel,
       n.nombre_nivel,
       g.id AS grado_id,
       g.numero_grado,
       g.nombre_grado,
       s.id AS seccion_id,
       s.letra AS letra_seccion,
       au.codigo_aula,
       au.nombre_aula,
       s.cupo_maximo,
       s.vacantes_ocupadas,
       (s.cupo_maximo - s.vacantes_ocupadas) AS vacantes_disponibles,
       COUNT(m.id)::integer AS matriculados_confirmados
  FROM public.secciones s
  JOIN public.anios_lectivos al ON al.id = s.anio_lectivo_id
  JOIN public.grados g ON g.id = s.grado_id
  JOIN public.niveles n ON n.id = g.nivel_id
  JOIN public.aulas au ON au.id = s.aula_id
  LEFT JOIN public.matriculas m
    ON m.seccion_id = s.id
   AND m.anio_lectivo_id = s.anio_lectivo_id
   AND m.estado_matricula = 'MATRICULADO'
 GROUP BY al.id, al.anio, n.id, n.codigo_nivel, n.nombre_nivel,
          g.id, g.numero_grado, g.nombre_grado, s.id, s.letra,
          au.codigo_aula, au.nombre_aula, s.cupo_maximo, s.vacantes_ocupadas;

CREATE OR REPLACE VIEW public.v_directorio_docentes_cursos
WITH (security_invoker = true) AS
SELECT u.id AS docente_usuario_id,
       u.nombre_usuario,
       u.nombre_completo,
       u.correo_electronico,
       u.dni,
       u.especialidad,
       u.activo,
       u.estado_laboral,
       COUNT(dac.area_curricular_id)::integer AS cantidad_cursos,
       COALESCE(
         STRING_AGG(DISTINCT n.nombre_nivel || ': ' || ac.nombre_area, ' | '
                    ORDER BY n.nombre_nivel || ': ' || ac.nombre_area),
         ''
       ) AS cursos_habilitados
  FROM public.usuarios u
  JOIN public.usuario_roles ur ON ur.usuario_id = u.id
  JOIN public.roles r ON r.id = ur.rol_id AND r.codigo_rol = 'DOCENTE'
  LEFT JOIN public.docente_areas_curriculares dac ON dac.docente_usuario_id = u.id
  LEFT JOIN public.areas_curriculares ac ON ac.id = dac.area_curricular_id AND ac.nivel_id = dac.nivel_id
  LEFT JOIN public.niveles n ON n.id = dac.nivel_id
 GROUP BY u.id, u.nombre_usuario, u.nombre_completo, u.correo_electronico,
          u.dni, u.especialidad, u.activo, u.estado_laboral;

CREATE OR REPLACE VIEW public.v_horarios_completos_grado_seccion
WITH (security_invoker = true) AS
SELECT hs.id AS horario_id,
       al.id AS anio_lectivo_id,
       al.anio,
       n.id AS nivel_id,
       n.nombre_nivel,
       g.id AS grado_id,
       g.nombre_grado,
       s.id AS seccion_id,
       s.letra AS letra_seccion,
       au.codigo_aula,
       hs.dia_semana,
       CASE hs.dia_semana
         WHEN 1 THEN 'LUNES'
         WHEN 2 THEN 'MARTES'
         WHEN 3 THEN 'MIERCOLES'
         WHEN 4 THEN 'JUEVES'
         ELSE 'VIERNES'
       END AS dia_nombre,
       bh.id AS bloque_horario_id,
       bh.numero_bloque,
       bh.hora_inicio,
       bh.hora_fin,
       ac.id AS area_curricular_id,
       ac.codigo_area,
       ac.nombre_area,
       u.id AS docente_usuario_id,
       u.nombre_completo AS docente_nombre
  FROM public.horarios_seccion hs
  JOIN public.anios_lectivos al ON al.id = hs.anio_lectivo_id
  JOIN public.secciones s ON s.id = hs.seccion_id
  JOIN public.grados g ON g.id = s.grado_id
  JOIN public.niveles n ON n.id = g.nivel_id
  JOIN public.aulas au ON au.id = s.aula_id
  JOIN public.asignaciones_docentes ad ON ad.id = hs.asignacion_docente_id
  JOIN public.areas_curriculares ac ON ac.id = ad.area_curricular_id
  JOIN public.usuarios u ON u.id = hs.docente_usuario_id
  JOIN public.bloques_horarios bh ON bh.id = hs.bloque_horario_id
 WHERE hs.activo IS TRUE;

-- 5. Horarios y mallas curriculares para TODOS los 14 grados (sin colisiones)
ALTER TABLE public.mallas_horarias_grado DISABLE TRIGGER trg_auditar_mallas_horarias_grado;
ALTER TABLE public.asignaciones_docentes DISABLE TRIGGER trg_auditar_asignaciones_docentes;
ALTER TABLE public.horarios_seccion DISABLE TRIGGER trg_auditar_horarios_seccion;

