ALTER TABLE public.mallas_horarias_grado ENABLE TRIGGER trg_auditar_mallas_horarias_grado;
ALTER TABLE public.asignaciones_docentes ENABLE TRIGGER trg_auditar_asignaciones_docentes;
ALTER TABLE public.horarios_seccion ENABLE TRIGGER trg_auditar_horarios_seccion;

SELECT setval(pg_get_serial_sequence('public.mallas_horarias_grado', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM public.mallas_horarias_grado), 1), true);
SELECT setval(pg_get_serial_sequence('public.asignaciones_docentes', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM public.asignaciones_docentes), 1), true);
SELECT setval(pg_get_serial_sequence('public.horarios_seccion', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM public.horarios_seccion), 1), true);

